package com.skyrpg.minions;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;
import net.minecraft.resources.Identifier;

/**
 * Minion fuels, from {@code data/skyrpg_minions/skyrpg/minion_fuels/*.json} (generated by
 * {@code tools/skyblock/import_minions.py} from Hypixel's item lore): how much faster a minion works while it burns,
 * how much more it makes (Catalysts), and how long one lasts in real minutes (0: forever, like a Lava Bucket).
 */
public final class MinionFuels {
    public static final String DIRECTORY = "skyrpg/minion_fuels";

    public record Fuel(String item, int speed, int multiplier, int minutes) {
        public boolean forever() {
            return minutes <= 0;
        }

        public long millis() {
            return minutes * 60_000L;
        }
    }

    private static Map<String, Fuel> fuels = Map.of();

    private MinionFuels() {
    }

    static void load(Map<Identifier, JsonElement> files) {
        Map<String, Fuel> loaded = new LinkedHashMap<>();
        files.forEach((id, element) -> {
            try {
                JsonObject json = element.getAsJsonObject();
                Fuel fuel = new Fuel(json.get("item").getAsString(), json.get("speed").getAsInt(),
                        Math.max(1, json.get("multiplier").getAsInt()), json.get("minutes").getAsInt());
                loaded.put(fuel.item(), fuel);
            } catch (RuntimeException e) {
                SkyRpgMinions.LOGGER.error("Skipping invalid minion fuel {}: {}", id, e.getMessage());
            }
        });
        fuels = loaded;
        SkyRpgMinions.LOGGER.info("Loaded {} minion fuels", loaded.size());
    }

    public static Collection<Fuel> all() {
        return fuels.values();
    }

    /** The fuel this SkyBlock item is, or null. */
    public static Fuel get(String skyblockId) {
        return skyblockId == null ? null : fuels.get(skyblockId);
    }
}
